automations:
{
  "alias": "SleepyPod Synthetic bedroom temperature",
  "description": "Read-only sensor publisher. Verify the timestamp attribute is the source measurement time before enabling. Does not control the Pod or accessories.",
  "triggers": [
    {
      "trigger": "state",
      "entity_id": "sensor.example_temperature"
    },
    {
      "trigger": "time_pattern",
      "seconds": "/30"
    }
  ],
  "actions": [
    {
      "action": "mqtt.publish",
      "data": {
        "topic": "example/controller/room/report",
        "qos": 0,
        "retain": false,
        "payload": "{% set raw_time = as_timestamp(state_attr('sensor.example_temperature', 'measured_at'), none) %}\n{% set measurement = (raw_time * 1000) | int if raw_time is not none else none %}\n{% set raw_value = states('sensor.example_temperature') | float(none) %}\n{% set usable = raw_value is not none and measurement is not none and state_attr('sensor.example_temperature', 'unit_of_measurement') == '°C' %}\n{{ {'schemaVersion': 1, 'source': 'home_assistant', 'revision': 7, 'metric': 'temperature', 'entityId': 'sensor.example_temperature', 'unit': '°C', 'reportedAt': (as_timestamp(now()) * 1000) | int, 'measuredAt': measurement if usable else none, 'available': usable, 'value': raw_value if usable else none} | to_json }}"
      }
    }
  ],
  "mode": "single"
}

